static u8 cal_crc8_0x31(u8 *data_buf, u16 len)
{
	u8    crc = 0x00;

#if MB_UART_CRC8_ENABLE
	for (u16 i = 0; i < len; i++)
	{
		crc = crc8_table[crc ^ data_buf[i]];
	}
#endif

	return (crc);
}

